CustomField.formula:
IF(
/*If Account is IMGA, stores stores Strategic Account value */
ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), Sales_Strategic_Account__c,
IF(
/*If Account is Country Parent, stores IMGA Account's stores Strategic Account value by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Parent.Sales_Strategic_Account__c ,
IF(
/*If Account is Sales site, stores IMGA Account's stores Strategic Account value by traversing two levels up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(Parent.ParentId))), Parent.Parent.Sales_Strategic_Account__c,Sales_Strategic_Account__c)))
